typedef struct { int calls; char last[32]; } shunt_t;   /* the test object */
static void on_event(void *ctx, const char *name) {     /* SUT calls this */
    shunt_t *self = ctx;
    self->calls++;
    snprintf(self->last, sizeof self->last, "%s", name);
}
static void test_publishes_once(void) {
    shunt_t self = {0};
    subject_t *s = subject_new(on_event, &self);        /* install the shunt */
    subject_change(s, "x");
    assert_int_equal(1, self.calls);                    /* observe on it */
}
